import { useRef, useState } from 'react';
import { motion } from 'framer-motion';
import NamedIcon from '../../components/NamedIcon';

export default function TiltCard() {
  const ref = useRef<HTMLDivElement>(null);
  const [rotate, setRotate] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const x = (e.clientY - rect.top - rect.height / 2) / 10;
    const y = -(e.clientX - rect.left - rect.width / 2) / 10;
    setRotate({ x, y });
  };

  const handleMouseLeave = () => setRotate({ x: 0, y: 0 });

  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: 300, perspective: 1000 }}>
      <motion.div
        ref={ref}
        animate={{ rotateX: rotate.x, rotateY: rotate.y }}
        transition={{ type: 'spring', stiffness: 200, damping: 20 }}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{
          width: 320,
        maxWidth: '100%',
          padding: 'var(--space-8)',
          borderRadius: 'var(--radius-xxl)',
          background: 'var(--color-bg-elevated)',
          border: '1px solid var(--color-border-default)',
          boxShadow: 'var(--shadow-xl)',
          transformStyle: 'preserve-3d',
        }}
      >
        <div
          style={{
            width: 48,
            height: 48,
            borderRadius: 'var(--radius-lg)',
            background: 'linear-gradient(135deg, var(--color-primary), var(--color-secondary))',
            marginBottom: 'var(--space-5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '24px',
          }}
        >
          <NamedIcon name="sparkling-2-line" size={24} />
        </div>
        <h3 style={{ fontSize: 'var(--text-xl)', fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: 'var(--space-2)' }}>
          3D 倾斜卡片
        </h3>
        <p style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-secondary)', lineHeight: 'var(--leading-relaxed)' }}>
          移动鼠标时卡片会跟随产生 3D 倾斜效果，松开后平滑回弹。
        </p>
        <div style={{ marginTop: 'var(--space-5)', display: 'flex', gap: 'var(--space-2)' }}>
          <span style={{ padding: 'var(--space-1) var(--space-3)', borderRadius: 'var(--radius-full)', background: 'var(--color-bg-active)', fontSize: 'var(--text-xs)', color: 'var(--color-text-secondary)' }}>
            3D
          </span>
          <span style={{ padding: 'var(--space-1) var(--space-3)', borderRadius: 'var(--radius-full)', background: 'var(--color-bg-active)', fontSize: 'var(--text-xs)', color: 'var(--color-text-secondary)' }}>
            Interactive
          </span>
        </div>
      </motion.div>
    </div>
  );
}

